/* ---------- Online Examination: opens the BUCM Online Examination in a new tab ---------- */
/* EXAM_URL: the full address of BUCM_ONLINE_EXAM.html (the app runs inside a protected frame, so the address must be complete). */
var EXAM_URL='https://plereapapp-itteam.github.io/MMABU-PLEREAP/BUCM_ONLINE_EXAM.html';
window.PLE27openExam=function(){var ps=window.PLE_STUDENT||{}, a=ps.reportAuth||{}, code=String(a.code||ps.code||''), nm='';
  try{nm=profName()||String(ps.name||'')}catch(e){}
  var h=[]; if(code)h.push('code='+encodeURIComponent(code)); if(nm)h.push('name='+encodeURIComponent(nm));
  var u=EXAM_URL+(h.length?'#'+h.join('&'):''), w=window.open(u,'_blank'); if(w){try{w.opener=null}catch(e){}} else location.href=u};

/* ---------- plates and navigation ---------- */
var plates=$$('section.plate'), ids=plates.map(function(p){return p.dataset.id});
var EMPTY={};
var DESC={exam:'The BUCM Online Examination of your year level. It opens in a new tab and uses your access code',theme:'The art behind the look: Abel Iloko, the handwoven textile of the Ilocos region',tree:'Your ultimate goal: a living golden tree that grows as you complete your year level’s subjects. Its full growth is the measure of your hard work',cases:'Let’s Heal: 28 patient cases in two modes, explained on the plate: Across the Disciplines, a self-paced walk through every subject, and In Real World, a live simulation on a running clock',today:'What to study today, what is due, readiness by subject, sessions that fit the time you have and your error log',snakes:'Snakes and ladders against a simulated Rival Intern: answer correctly to earn every roll, with event squares, ladders and snakes',jackpot:'The 45-item Jackpot Quest: 15 sets of 3, 60 seconds each, one miss and you start again; 20 notes to start, refilled by Wheel of Fortune jackpots up to 100',wheel:'Spin, answer within 60 seconds, and grow your bank to ₱100,000 for the Grand Jackpot, which adds 10 notes to the Jackpot Round',cover:'My Med APP by PLE REAP: the app at a glance',contents:'Every section and plate',mnemo:'Active-recall practice with mnemonics for every subject, with a search by topic',flash:'Flip-and-rate flashcards by subject and topic, for every subject, with a search by topic',mcq:'Two volumes of practice questions by subject, with a search by topic, 10 to 100 item trial exams drawn from both volumes, and analytics',sim:'The Comprehensive Examination Simulation: a 100-item paper per subject on the Table of Specifications, with a flip-through questionnaire, a bubble answer sheet and three compared trials',stories:'Nine illustrated storybooks about the road to the white coat',podcasts:'Six audio companions for worry, fear and anxiety before the examination',value:'Topic weights and cognitive levels for all 12 subjects, with the six levels of Bloom’s taxonomy explained and a sample question for each',progress:'Your accomplishments: study-guide tasks done, assessment scores, and reading progress in Let’s Build and Let’s Exercise',welcome:'A message for the future physician',company:'About PLE REAP Medicine: the name, vision, mission, tools and impact so far',design:'Your study cockpit with today’s checklist, one-tap tasks, a focus timer, a study heatmap and badges, plus a plan per subject brought together in My week',funnel:'Six screens that narrow broad topics to what is likely to be asked',outcomes:'Six outcomes and how each is measured across the three phases',blueprint:'Modular Sheets for all 24 subjects, chapter by chapter, with a syllabus finder and a 10-question Chapter Boss at the end of every chapter',masterclass:'Rapid Review Sheets for all 24 subjects, chapter for chapter the same as Let’s Build, for active recall',subjects:'Your master switchboard: switch subjects off for now and back on any time, so only what you need shows in every plate'};
var seen={}; try{seen=JSON.parse(store.get('ple27seen')||'{}')||{}}catch(e){seen={}}
var nav=$('#nav'), toc=$('#toc'), cur=0;
var tocX=null;
plates.forEach(function(p,i){
  var b=document.createElement('button'); b.type='button';
  b.style.setProperty('--k',p.dataset.c); b.innerHTML='<span class="num">'+p.dataset.n+'</span><span>'+p.dataset.t+'</span>'+(EMPTY[p.dataset.id]?'<span class="tag">To follow</span>':'<span class="em">'+p.dataset.e+'</span>');
  var isX=p.dataset.n.indexOf('.')>0, sec=p.dataset.n.split('.')[0], SN={XI:['SDL Resources','Three resources for self-directed learning, each with its own plate'],XII:['Self-Assessment Tools','Five tools for testing yourself'],XV:['Gamification','Three games that test your recall against the clock']}[sec];
  if(isX&&/\.1$/.test(p.dataset.n)){var gh=document.createElement('div'); gh.className='nav-x'; gh.innerHTML='<span class="num">'+sec+'</span><span>'+SN[0]+'</span>'; nav.appendChild(gh);
    tocX=document.createElement('div'); tocX.className='toc-x'; tocX.innerHTML='<div class="toc-xh"><span class="n">'+sec+'</span><span><small>PLATE '+sec+'</small>'+SN[0]+'<i>'+SN[1]+'</i></span></div><div class="toc-xg"></div>'; toc.appendChild(tocX)}
  if(isX)b.classList.add('sub');
  b.addEventListener('click',function(){ if(p.dataset.link){PLE27openExam(); return} go(i)}); nav.appendChild(b);
  if(p.dataset.id!=='contents'){
    var c=document.createElement('button'); c.type='button'; if(EMPTY[p.dataset.id])c.className='tf';
    c.style.setProperty('--k',p.dataset.c); c.innerHTML='<span class="n">'+p.dataset.e+'</span><span><span class="t"><small>PLATE '+p.dataset.n+'</small>'+p.dataset.t+'</span><span class="d">'+DESC[p.dataset.id]+'</span></span>'+(EMPTY[p.dataset.id]?'<span class="tag">To follow</span>':'');
    c.addEventListener('click',function(){ if(p.dataset.link){PLE27openExam(); return} go(i)}); (isX&&tocX?tocX.lastChild:toc).appendChild(c);
  }
});
var navB=$$('button',nav);
var bootGo=true, waitGo=null, LATE={"tree": 1};
function go(i,silent){ if(!bootGo&&document.readyState==='loading'&&LATE[typeof i==='string'?i:ids[i]]){ if(!waitGo){document.addEventListener('DOMContentLoaded',function(){var w=waitGo; waitGo=null; var n=document.getElementById('bootNote'); if(n)n.remove(); go(w[0],w[1])})}
    waitGo=[i,silent]; if(!document.getElementById('bootNote')){var n=document.createElement('div'); n.id='bootNote'; n.setAttribute('role','status'); n.textContent='Opening… one moment while the app finishes unpacking.'; n.style.cssText='position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:2147483600;padding:10px 18px;border-radius:99px;background:rgba(20,24,40,.94);color:#fff;font:600 .9rem system-ui,sans-serif;box-shadow:0 8px 24px rgba(0,0,0,.35)'; document.body.appendChild(n)} return}
  bootGo=false;   if(typeof i==='string')i=ids.indexOf(i);
  if(i<0||i>=plates.length)return;
  cur=i;
  plates.forEach(function(p,k){p.hidden=k!==i});
  navB.forEach(function(b,k){b.classList.toggle('on',k===i)});
  seen[ids[i]]=1; store.set('ple27seen',JSON.stringify(seen));
  navB.forEach(function(b,k){b.classList.toggle('seen',!!seen[ids[k]])});
  var n=ids.filter(function(x){return seen[x]}).length;
  $('#progT').textContent=n+' / '+ids.length; $('#progB').style.width=(n/ids.length*100)+'%';
  $('#topT').textContent=plates[i].dataset.n+' · '+plates[i].dataset.t;
  $('#prevBtn').style.visibility=i?'visible':'hidden'; $('#nextBtn').style.visibility=i<plates.length-1?'visible':'hidden';
  if(!silent){try{history.replaceState(null,'','#'+ids[i])}catch(e){}}
  $('#stage').scrollTop=0; if(window.innerWidth<=900)window.scrollTo(0,0);
  closeRail();
  document.body.style.setProperty('--pc',plates[i].dataset.c);
  document.dispatchEvent(new CustomEvent('plate',{detail:ids[i]}));
}
$('#prevBtn').addEventListener('click',function(){go(cur-1)});
$('#nextBtn').addEventListener('click',function(){go(cur+1)});
document.addEventListener('click',function(e){var t=e.target.closest('[data-go]'); if(t)go(t.dataset.go)});
document.addEventListener('keydown',function(e){
  if(e.target.closest&&e.target.closest('input,textarea'))return;
  if(document.body.classList.contains('jqc-open')||document.querySelector('.wfq,.jp-ban,.snq,.snm')||document.body.classList.contains('sn-live'))return;
  if(e.key==='ArrowRight')go(cur+1); else if(e.key==='ArrowLeft')go(cur-1);
});
var rail=$('#rail'), scrim=$('#scrim');
function closeRail(){rail.classList.remove('open');scrim.hidden=true}
$('#menuBtn').addEventListener('click',function(){rail.classList.add('open');scrim.hidden=false});
