/* ---------- theme ---------- */
function isDark(){var t=document.documentElement.dataset.theme; if(t)return t==='dark'; return !(window.matchMedia&&matchMedia('(prefers-color-scheme: light)').matches)}
function paintTheme(){var d=isDark(); $('#themeBtn').textContent=d?'Day mode':'Night mode'; $('#themeBtn2').textContent=d?'Day':'Night'; starRGB='255,244,214'}
function toggleTheme(){var n=isDark()?'light':'dark'; document.documentElement.dataset.theme=n; store.set('ple27theme',n); paintTheme(); document.dispatchEvent(new CustomEvent('themechange'))}
var starRGB='255,244,214', st=store.get('ple27theme'); document.documentElement.dataset.theme=st==='light'?'light':'dark';
function paintGray(){var g=document.documentElement.classList.contains('gray'); ['#grayBtn','#grayBtn2'].forEach(function(q){var b=$(q); b.setAttribute('aria-pressed',g?'true':'false'); b.classList.toggle('on',g)}); $('#grayBtn').textContent=g?'Grayscale ✓':'Grayscale'}
