var fcv=$('#fcv'), fx=fcv.getContext('2d'), FP=[], G=null, fcol={}, fraf=0, fdpr=Math.min(2,window.devicePixelRatio||1);
function fmeasure(){var R=fun.getBoundingClientRect(); if(!R.width)return; fcv.width=R.width*fdpr; fcv.height=R.height*fdpr;
  var bs=$$('.band',bands), a=bs[0].getBoundingClientRect(), z=bs[5].getBoundingClientRect(), o=fout.getBoundingClientRect(), m=mouth.getBoundingClientRect();
  G={W:R.width,H:R.height,top:a.top-R.top,bot:z.bottom-R.top,cx:a.left-R.left+a.width/2,w:a.width,my:m.top-R.top,oy:o.top-R.top+o.height/2,tops:bs.map(function(b){return b.getBoundingClientRect().top-R.top})};
  fcol={g:'#F2C14E',r:'#FF7A6E',n:'#C9D4EA'}}
function hw(y){var f=Math.max(0,Math.min(1,(y-G.top)/(G.bot-G.top))); return G.w/2-f*6*0.046*G.w}
function spawn(){FP.push({x:G.cx+(Math.random()-.5)*G.w*.9,y:G.my+Math.random()*20,vx:0,vy:.7+Math.random()*.9,s:0,k:0,a:1,r:1.4+Math.random()*1.8})}
function burst(){if(!G)return; for(var i=0;i<46;i++){var an=Math.random()*6.28, sp=1+Math.random()*3.5; FP.push({x:G.cx,y:G.oy,vx:Math.cos(an)*sp,vy:Math.sin(an)*sp-1,s:3,a:1,r:1.5+Math.random()*2})}}
function ftick(){ fraf=0; if(ids[cur]!=='funnel'||!G)return;
  fx.setTransform(fdpr,0,0,fdpr,0,0); fx.clearRect(0,0,G.W,G.H);
  if(FP.length<150&&Math.random()<.5)spawn();
  for(var i=FP.length-1;i>=0;i--){var p=FP[i];
    if(p.s===0){ p.y+=p.vy; var h=hw(p.y)-5, dx=p.x-G.cx; if(Math.abs(dx)>h)p.x=G.cx+(dx>0?h:-h); p.x+=(Math.random()-.5)*.6;
      if(p.k<6&&p.y>=G.tops[p.k]){ if(Math.random()<.27){p.s=1; p.vx=(p.x>=G.cx?1:-1)*(2.2+Math.random()*2.4); p.vy=-1.2-Math.random(); p.hit=p.k} p.k++ }
      if(p.y>G.bot)p.s=2 }
    else if(p.s===1){ p.x+=p.vx; p.y+=p.vy; p.vy+=.07; p.a-=.014 }
    else if(p.s===2){ p.y+=1.6; p.x+=(G.cx-p.x)*.2; if(p.y>G.oy){p.a-=.08} }
    else { p.x+=p.vx; p.y+=p.vy; p.vy+=.06; p.a-=.02 }
    if(p.a<=0||p.x<-10||p.x>G.W+10){FP.splice(i,1);continue}
    var hot=p.s===1&&p.hit===fi;
    fx.globalAlpha=Math.max(0,p.a)*(p.s===0?.75:1); fx.fillStyle=p.s===1?fcol.r:p.s===0?fcol.n:fcol.g;
    fx.beginPath(); fx.arc(p.x,p.y,p.r*(hot?1.7:1),0,6.28); fx.fill();
    if(p.s===1){fx.globalAlpha=Math.max(0,p.a)*.35; fx.strokeStyle=fcol.r; fx.lineWidth=1; fx.beginPath(); fx.moveTo(p.x,p.y); fx.lineTo(p.x-p.vx*5,p.y-p.vy*5); fx.stroke()}
  }
  fx.globalAlpha=1; fraf=requestAnimationFrame(ftick)}
function fstart(){ fmeasure(); if(!reduce&&!fraf)fraf=requestAnimationFrame(ftick)}
document.addEventListener('plate',function(e){ if(e.detail==='funnel')setTimeout(fstart,80)});
addEventListener('resize',function(){ if(ids[cur]==='funnel')fmeasure()});
fun.addEventListener('pointermove',function(e){ if(reduce||window.innerWidth<=900)return; var r=fun.getBoundingClientRect(), x=(e.clientX-r.left)/r.width-.5, y=(e.clientY-r.top)/r.height-.5; fun.style.transform='perspective(1100px) rotateY('+(x*5)+'deg) rotateX('+(-y*4)+'deg)'});
