/* day picker */
var days=$('#vcDays');
[1,2,3,4].forEach(function(d){var w=document.createElement('div'); w.className='vc-day'; w.innerHTML='<b>Day '+d+'</b><div></div>';
  VC.forEach(function(s,i){ if(s.day!==d)return; var b=document.createElement('button'); b.type='button'; b.style.setProperty('--k',s.c); b.innerHTML='<span>'+s.e+'</span>'+esc(s.n); b.addEventListener('click',function(){pick(i,true)}); w.lastChild.appendChild(b); s.b=b}); days.appendChild(w)});
function save(){store.set('ple27vc',JSON.stringify(chk))}
