function both(fn){ if(VST[0].DATA&&VST[1].DATA)return true; body.innerHTML='<div class="bp-load">Opening Volumes 1 and 2…</div>'; Promise.all([load(0),load(1)]).then(fn,function(){body.innerHTML='<div class="mq-empty">The question bank could not be opened in this browser. Please update your browser and try again.</div>'}); return false}
