function examStart(){var s=sj(), z=ps(), ids=tosDraw(s.k,z.ts||[],z.xn,z.xw!==false); if(!ids.length)return; X={k:s.k,n:ids.length,ids:ids,ans:{},fl:{},at:0,used:0,lim:z.xt?ids.length*72:0}; R=null; saveX(); exam(); panel.scrollIntoView({block:'start'})}
