/* Comprehensive Examination cloud upload — standalone Worker; keeps local results authoritative for display.
   The server accepts self-reported results. Do not use this as verified high-stakes grading. */
var MED_EXAM_API='https://my-med-comprehensive-api.ple-reap-app.workers.dev/api/comprehensive/results';
var MED_QUEUE_KEY='ple27comprehensiveUploadQueue', MED_STUDENT_KEY='ple27comprehensiveStudentId';
var medUploadBusy=false;
function medStudentId(){
  var v=store.get(MED_STUDENT_KEY);
  if(v&&/^[a-zA-Z0-9_-]{8,100}$/.test(v))return v;
  var u=new Uint8Array(16); crypto.getRandomValues(u);
  v='med-'+Array.from(u,function(x){return x.toString(16).padStart(2,'0')}).join('');
  store.set(MED_STUDENT_KEY,v);return v;
}
function medQueue(){try{var a=JSON.parse(store.get(MED_QUEUE_KEY)||'[]');return Array.isArray(a)?a:[]}catch(e){return []}}
function medFlush(){
  if(medUploadBusy||!navigator.onLine)return;
  var q=medQueue(); if(!q.length)return;
  medUploadBusy=true;
  (async function(){
    for(var i=0;i<q.length;i++){
      var p=q[i];
      try{
        var r=await fetch(MED_EXAM_API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p),cache:'no-store'});
        if(!r.ok)throw Error('HTTP '+r.status);
        var j=await r.json();if(j.ok!==true)throw Error(j.error||'Not saved');
        // Keep any newly queued records, remove only the acknowledged submission.
        var fresh=medQueue().filter(function(x){return x.submission_id!==p.submission_id});
        store.set(MED_QUEUE_KEY,JSON.stringify(fresh));
      }catch(e){console.warn('Comprehensive score upload pending; will retry:',e);break}
    }
  })().finally(function(){medUploadBusy=false});
}
function medRecordAttempt(k,R,identity){
  if(!R)return;
  if(!R.cloud_submission_id){
    var a=new Uint8Array(16);crypto.getRandomValues(a);
    R.cloud_submission_id='med-'+Array.from(a,function(x){return x.toString(16).padStart(2,'0')}).join('');
    save(); // Preserve the same submission ID across retries.
  }
  var row={submission_id:R.cloud_submission_id,student_id:medStudentId(),
    student_name:String(identity.n||'').trim(),medical_school:String(identity.s||identity.m||'').trim(),
    subject_key:k,subject_name:(SJ.filter(function(x){return x.k===k})[0]||{}).n||k,
    trial_number:R.no,attempt_number:R.at,correct:R.c,total:NQ,skipped:R.sk,
    time_seconds:Math.max(0,Math.min(86400,Math.floor(R.t))),discarded:R.dc?1:0,
    completed_at:new Date(R.d).toISOString()};
  var q=medQueue();
  if(!q.some(function(x){return x.submission_id===row.submission_id})){
    q.push(row);store.set(MED_QUEUE_KEY,JSON.stringify(q));
  }
  medFlush();
}
window.addEventListener('online',medFlush);
window.addEventListener('focus',medFlush);
setInterval(medFlush,60000);
setTimeout(medFlush,2500);

