function ple27txt(id){var e=document.getElementById(id); if(!e&&document.readyState==='loading')return new Promise(function(res){document.addEventListener('DOMContentLoaded',function(){res()},{once:true})}).then(function(){return ple27txt(id)}); if(!e)return Promise.reject(new Error('missing')); if(e._p)return e._p;
  var ds=e.getAttribute('data-src'); if(ds&&!e.textContent.trim()){e._p=fetch(ds).then(function(r){ if(!r.ok)throw new Error('fetch'); return r.text()}).then(function(t){e.textContent=t; e._p=null; return ple27txt(id)}); return e._p}
  if(!e.hasAttribute('data-z'))return Promise.resolve(e.textContent);
  e._p=new Promise(function(res,rej){try{ if(typeof DecompressionStream==='undefined')throw new Error('unsupported'); var bin=atob(e.textContent.trim()), n=bin.length, u=new Uint8Array(n); for(var i=0;i<n;i++)u[i]=bin.charCodeAt(i);
    new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).text().then(res,rej)}catch(err){rej(err)}}); return e._p}
