/* ---------- floating highlighter (Blueprint Phase · Modular Sheets only) ---------- */
(function(){var bar=$('#hlBar'); if(!bar)return; var sec=$('[data-id="blueprint"]'), pane=$('#bpSheet'), mode=null, open=false, armed=0;
var NM={y:'Yellow',r:'Red',b:'Blue',erase:'Eraser'};
function frame(){return $$('#bpFrame iframe').filter(function(f){return !f.hidden})[0]}
function send(o){var f=frame(); if(f&&f.contentWindow){o.ple27=1; try{f.contentWindow.postMessage(o,'*')}catch(e){}}}
function paint(){$$('[data-hl]',bar).forEach(function(b){var on=b.dataset.hl===(mode||'off'); b.classList.toggle('on',on); b.setAttribute('aria-pressed',on)});
  bar.classList.toggle('open',open); bar.classList.toggle('active',!!mode); $('#hlState').textContent=mode?(mode==='erase'?'Eraser: tap a highlight to remove it':NM[mode]+': select text to highlight'):'Highlighter off'}
function set(m){mode=m==='off'?null:m; paint(); send({hl:mode})}
function vis(){var f=frame(), show=sec&&!sec.hidden&&pane&&!pane.hidden&&!!f; if(show){var r=f.getBoundingClientRect(); show=r.height>40&&r.top<innerHeight-120&&r.bottom>120} bar.hidden=!show}
bar.addEventListener('click',function(e){var b=e.target.closest('button'); if(!b)return;
  if(b.id==='hlTog'){open=!open; if(!open)set('off'); else paint(); return}
  if(b.id==='hlMin'){mini(!bar.classList.contains('mini')); return}
  if(b.dataset.hl){set(b.dataset.hl===mode?'off':b.dataset.hl); return}
  if(b.id==='hlClr'){ if(!armed){armed=setTimeout(function(){armed=0; b.textContent='🧹 Remove all highlights in this chapter'; b.classList.remove('warn')},3500); b.textContent='Tap again to remove them all'; b.classList.add('warn'); return}
    clearTimeout(armed); armed=0; b.textContent='🧹 Remove all highlights in this chapter'; b.classList.remove('warn'); send({hlClear:1})}});
window.addEventListener('message',function(e){var d=e.data; if(!d||!d.ple27)return;
  if(d.ready){var f=frame(); if(f&&e.source===f.contentWindow)setTimeout(function(){send({hl:mode}); send({hlAsk:1})},50)}
  if('hlCount' in d){var f2=frame(); if(f2&&e.source===f2.contentWindow)$('#hlN').textContent=d.hlCount?d.hlCount+' highlight'+(d.hlCount>1?'s':'')+' in this chapter':'No highlights in this chapter yet'}
  if(d.active){setTimeout(function(){send({hlAsk:1})},120)}});
/* minimise: the panel shrinks to one small row and the chosen colour stays on */
$$('[data-hl]',bar).forEach(function(b){var t=b.textContent.trim(), m=/^(\S+)\s+(.+)$/.exec(t), ic=b.dataset.hl==='erase'||b.dataset.hl==='off';
  b.setAttribute('aria-label',ic&&m?m[2]:t); b.title=ic&&m?m[2]:t; b.innerHTML=ic&&m?'<i aria-hidden="true">'+m[1]+'</i><span class="t"> '+m[2]+'</span>':'<span class="t">'+t+'</span>'});
function mini(on){bar.classList.toggle('mini',on); var mb=$('#hlMin'); if(mb){mb.textContent=on?'⤢':'–'; mb.title=on?'Show the full highlighter':'Minimise'; mb.setAttribute('aria-label',on?'Show the full highlighter panel':'Minimise the highlighter panel'); mb.setAttribute('aria-expanded',on?'false':'true')} try{localStorage.setItem('sidhaya27.ple27hlmini',on?'1':'0')}catch(e){}}
try{if(localStorage.getItem('sidhaya27.ple27hlmini')==='1')mini(true)}catch(e){}
setInterval(vis,400); vis(); paint();
document.addEventListener('click',function(e){ if(e.target.closest('#bpG0,#bpG1,#bpSPrev,#bpSNext,#bpChips'))setTimeout(function(){send({hl:mode}); send({hlAsk:1})},400)});
})();



