function rnd(a){return a[Math.floor(Math.random()*a.length)]}
var EPOCH=new Date(2026,0,1);
function dn(d){d=d?new Date(d):new Date(); return Math.round((new Date(d.getFullYear(),d.getMonth(),d.getDate())-EPOCH)/864e5)}
function dOf(n){return new Date(EPOCH.getFullYear(),EPOCH.getMonth(),EPOCH.getDate()+n)}
