function srsHit(key){var o=S.it[key]; if(!o||o.d>TODAY)return; var n=null; for(var i=0;i<STEPS.length;i++)if(STEPS[i]>o.iv){n=STEPS[i];break} o.iv=n||o.iv*2; o.d=TODAY+o.iv; o.r=(o.r||0)+1}
function tp(k,v,i){var t=TOS[k]&&TOS[k].t[v]; if(!t)return -1; var d=t.charCodeAt(i)-66; return d>=0&&d<TOS[k].d.length?d:-1}
