function pk(key){var p=key.split('|'); return {t:p[0],v:p[0]==='f'?-1:+p[0].slice(1)-1,k:p[1],i:+p[2]}}

/* the single answer hook every module reports to */
window.PLE27ans=function(t,k,i,ok,a,src){ if(!k||i==null||i<0)return; var key=t+'|'+k+'|'+i;
  if(t!=='f'){var o=I[key]||[0,0,0,0]; o[0]++; if(ok)o[1]++; o[2]=ok?1:0; o[3]=TODAY; I[key]=o;
    if(!ok){var e=E[key]||{d:Date.now(),n:0,note:'',ok:0}; e.n++; e.a=a; e.l=Date.now(); e.ok=0; e.s=src||''; E[key]=e} else if(E[key]&&src==='today'&&S.it[key]&&S.it[key].r>=2)E[key].ok=1}
  if(ok)srsHit(key); else srsMiss(key);
  A[TODAY]=(A[TODAY]||0)+1; saveAll(); dirty=true};
var dirty=true;

/* one-time import of what was answered before this update */
if(store.get('ple27bf')!=='1'){try{var spread=0;
  function bf(key,ok,src){var o=I[key]||[0,0,0,0]; o[0]++; if(ok)o[1]++; o[2]=ok?1:0; o[3]=o[3]||TODAY-1; I[key]=o; if(!ok){ if(!E[key])E[key]={d:Date.now(),n:1,note:'',ok:0,s:src}; if(!S.it[key])srsMiss(key,TODAY+(spread++%7))}}
  [['ple27mcq',1],['ple27mcqv2',2]].forEach(function(p){var P=jget(p[0],{}); if(P&&P.pr)Object.keys(P.pr).forEach(function(k){var o=P.pr[k]; for(var i in o)bf('m'+p[1]+'|'+k+'|'+i,o[i]===1,'practice')})});
  ['ple27sim','sd27mile'].forEach(function(n){var R=jget(n,{}); Object.keys(R||{}).forEach(function(k){(R[k].tr||[]).forEach(function(r){(r.it||[]).forEach(function(x){bf('m'+(x[0]+1)+'|'+k+'|'+x[1],!!x[3],'exam')})})})});
  var F=jget('ple27fc2',{}); Object.keys(F).forEach(function(k){for(var i in F[k])if(F[k][i]===0){var key='f|'+k+'|'+i; if(!S.it[key])srsMiss(key,TODAY+(spread++%7))}});
  jset('ple27srs',S); jset('ple27ist',I); jset('ple27err',E)}catch(e){} store.set('ple27bf','1')}

/* ---------- data ---------- */
var MD=null, FD=null, IMG=null, loading=null;
function load(){ if(MD&&FD)return Promise.resolve(); if(!loading)loading=Promise.all([ple27json('mcqData'),ple27json('mcqData2'),ple27json('fcData2')]).then(function(r){MD=[r[0],r[1]]; FD=r[2]}); return loading}
function Qm(key){var p=pk(key); return MD&&MD[p.v]&&MD[p.v][p.k]?MD[p.v][p.k][p.i]:null}
function Cf(key){var p=pk(key); return FD&&FD[p.k]?FD[p.k].c[p.i]:null}
