/* ---------- my weak spots: the topics, questions and cases that keep going wrong ---------- */
var WK_OK=70, WK_MIN=3, WK_RW=75, wkAll=false;
function weakTopics(){var B=ready(), out=[]; Object.keys(B).forEach(function(k){var b=B[k]; if(!SB[k]||!TOS[k])return; TOS[k].d.forEach(function(d,i){var x=b.t[i]; if(x&&x[0]>=WK_MIN){var a=Math.round(x[1]/x[0]*100); if(a<WK_OK)out.push({k:k,i:i,n:d[0],w:d[1],a:a,c:x[0]})}})});
  return out.sort(function(a,b){return a.a-b.a||b.w-a.w})}
function repeats(){return Object.keys(E).filter(function(k){return !E[k].ok&&E[k].n>=2}).sort(function(a,b){return E[b].n-E[a].n})}
function rwWeak(){var L=[]; try{L=window.PLE27CX?window.PLE27CX.list():[]}catch(e){} return L.filter(function(c){return c.r&&c.r.runs&&c.r.last<WK_RW}).sort(function(a,b){return a.r.last-b.r.last})}
function paintWeak(){var box=$('#tdWeak'); if(!box)return; var T=weakTopics(), Rp=repeats(), C=rwWeak();
  var h='<p class="lead">Everything you keep getting wrong, gathered from every plate: topics below '+WK_OK+'% (after at least '+WK_MIN+' questions), questions you have missed more than once, and In Real World cases scored below '+WK_RW+'.</p>';
  h+='<div class="td-dn"><div style="--k:var(--c-red)"><b>'+T.length+'</b><span>weak topic'+(T.length===1?'':'s')+'</span></div><div style="--k:var(--c-amber)"><b>'+Rp.length+'</b><span>repeat miss'+(Rp.length===1?'':'es')+'</span></div><div style="--k:var(--c-purple)"><b>'+C.length+'</b><span>case'+(C.length===1?'':'s')+' to retry</span></div></div>';
  if(!T.length&&!Rp.length&&!C.length){box.innerHTML=h+'<p class="lead" style="margin-top:10px">No weak spots yet. They appear here once you have answered at least '+WK_MIN+' questions in a topic, or played an In Real World case.</p>'; return}
  h+='<div class="td-go"><button type="button" class="btn" data-wk="quiz"'+(T.length||Rp.length?'':' disabled')+'>🎯 Start a 10-question weak-spot quiz</button></div>';
  if(T.length){var show=wkAll?T:T.slice(0,6);
    h+='<h4 class="td-wh">Weakest topics</h4><ul class="td-wl">'+show.map(function(o){var s=SB[o.k]; return '<li style="--k:'+s.c+'"><span class="td-sj" style="--k:'+s.c+'">'+s.e+' '+esc(s.n.split(' and ')[0].split(',')[0])+'</span><span class="t"><b>'+esc(o.n)+'</b><small>'+o.a+'% right on '+o.c+' question'+(o.c===1?'':'s')+(o.w?' · '+o.w+'% of the subject in the Table of Specifications':'')+'</small></span><span class="td-wbar" aria-hidden="true"><i style="width:'+Math.max(4,o.a)+'%"></i></span><button type="button" class="btn ghost sm" data-wk="tp" data-k="'+o.k+'" data-i="'+o.i+'" aria-label="Practise '+esc(o.n)+'">Practise</button></li>'}).join('')+'</ul>';
    if(T.length>6)h+='<div class="td-go"><button type="button" class="btn ghost sm" data-wk="all">'+(wkAll?'Show fewer':'Show all '+T.length+' weak topics')+'</button></div>'}
  if(Rp.length){h+='<h4 class="td-wh">Questions I keep missing</h4><p class="td-wp">'+Rp.length+' question'+(Rp.length===1?' has':'s have')+' been missed two or more times and '+(Rp.length===1?'is':'are')+' not yet mastered. The one missed most often: '+E[Rp[0]].n+' times.</p><div class="td-go"><button type="button" class="btn ghost sm" data-wk="rep">Retry my repeat misses ('+Math.min(20,Rp.length)+')</button></div>'}
  if(C.length){h+='<h4 class="td-wh">In Real World cases to retry</h4><ul class="td-wc">'+C.map(function(c){var r=c.r, L=(r.crit&&r.crit.length?r.crit:(r.miss||[])), lab=r.crit?'Critical actions missed or critical errors':'Key steps missed';
      return '<li><div class="h"><span class="e" aria-hidden="true">'+(c.e||'🩺')+'</span><span class="t"><b>'+esc(c.n)+'</b><small>Last run '+r.last+'/100'+(r.lastT?' · '+esc(r.lastT):'')+' · best '+r.best+'/100 · '+r.runs+' run'+(r.runs===1?'':'s')+'</small></span><button type="button" class="btn sm" data-wk="case" data-id="'+esc(c.id)+'">↻ Retry this case</button></div>'+(L.length?'<div class="m"><span class="k">'+lab+'</span><ul>'+L.slice(0,5).map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+'</ul></div>':'')+'</li>'}).join('')+'</ul>';
    h+='<p class="td-wp">Retry the case before opening its debrief: work out what went wrong first.</p>'}
  box.innerHTML=h}
