'acs/ldl':{q:"His fasting lipids: total cholesterol 240, HDL 35, triglycerides 200 mg/dL. What is his calculated LDL?",f:"Friedewald: LDL = Total cholesterol − HDL − (Triglycerides ÷ 5)",ch:[["165 mg/dL",""],["205 mg/dL","This subtracts HDL but leaves out the VLDL term (triglycerides ÷ 5)."],["125 mg/dL","This divides triglycerides by 2.5 instead of 5."],["200 mg/dL","This subtracts VLDL but leaves out HDL."]]},
'stroke/dose':{q:"She weighs 60 kg and is eligible for IV alteplase. What is the total dose?",f:"Alteplase: 0.9 mg/kg (maximum 90 mg); 10% as a bolus over 1 minute, the rest over 60 minutes",ch:[["54 mg",""],["5.4 mg","This is only the 10% bolus."],["48.6 mg","This is only the infusion after the bolus."],["90 mg","90 mg is the maximum, used only at 100 kg or more."]]},
'dka/ag':{q:"Using her laboratory results, what is her anion gap?",f:"Anion gap = Na⁺ − (Cl⁻ + HCO₃⁻)",ch:[["26 mEq/L",""],["34 mEq/L","This subtracts only chloride."],["122 mEq/L","This subtracts only bicarbonate."],["18 mEq/L","Recheck the sum: 96 + 8 = 104."]]},
'dengue/rate':{ch:[["330 mL/hour",""],["33 mL/hour","This is one-tenth of the correct rate."],["165 mL/hour","This uses 3 mL/kg/hour."],["660 mL/hour","This uses 12 mL/kg/hour."]]},
'age/planb':{q:"Miko (10 kg) has some dehydration and will be treated with Plan B. How much ORS should he take in the first 4 hours?",f:"Plan B: ORS 75 mL/kg over 4 hours",ch:[["750 mL",""],["300 mL","This uses 30 mL/kg, the first step of Plan C."],["1,000 mL","This uses 100 mL/kg."],["75 mL","The rate must be multiplied by his weight."]]},
'newborn/amp':{ch:[["150 mg",""],["50 mg","This is the dose per kilogram, not per dose."],["450 mg","This multiplies by 3 doses; the question asks for one dose."],["17 mg","This divides the dose by the weight."]]},
'sam/f75':{q:"F-75 is started for Ana, who weighs 7.0 kg. What is her total daily volume?",f:"F-75 in stabilization: 130 mL/kg/day (100 mL/kg/day if she has severe edema), divided into 2-hourly feeds",ch:[["910 mL/day",""],["76 mL/day","This is the volume of one 2-hourly feed."],["700 mL/day","This uses 100 mL/kg/day, the amount for severe edema."],["1,300 mL/day","This uses 10 kg instead of her actual weight."]]},
'appy/alv':{q:"Using his history, examination and laboratory results, what is his Alvarado score?",f:"Alvarado: migration 1 · anorexia 1 · nausea/vomiting 1 · RLQ tenderness 2 · rebound 1 · fever ≥37.3 °C 1 · leukocytosis 2 · left shift 1",ch:[["9",""],["10","He has no rebound tenderness, so the maximum is not reached."],["8","Leukocytosis scores 2 points, not 1."],["7","RLQ tenderness scores 2 points."]]},
'trauma/gcs':{f:"GCS = Eyes (4) + Verbal (5) + Motor (6); here eyes to pain 2, inappropriate words 3, localizes pain 5",ch:[["10",""],["9","Localizing pain scores 5; withdrawal scores 4."],["11","Eye opening to pain scores 2, not 3."],["8","Inappropriate words score 3, not 2."]]},
'paputok/mf':{ch:[["1,800 mL/day",""],["3,500 mL/day","This uses 100 mL/kg for the whole weight."],["1,500 mL/day","This covers only the first 20 kg."],["2,200 mL/day","Above 20 kg, add 20 mL/kg, not 40 mL/kg."]]},
'pph/si':{q:"Using her vital signs on the monitor, what is her shock index?",f:"Shock index = heart rate ÷ systolic BP",ch:[["1.5",""],["0.66","This divides systolic BP by heart rate (the inverse)."],["1.0","Recheck the division: 124 ÷ 82."],["2.0","This overestimates the result."]]},
'pe/mgdose':{ch:[["20 mL",""],["4 mL","This assumes 1 g per mL."],["40 mL","This assumes a 10% solution."],["8 mL","This assumes a 50% solution."]]},
'teen/fe':{ch:[["65 mg",""],["325 mg","This is the weight of the whole salt, not the elemental iron."],["20 mg","20% is the proportion, not the amount."],["6.5 mg","This misplaces the decimal point."]]},
'anaph/epi':{q:"She weighs 60 kg. Epinephrine 1 mg/mL is available. How many mL should be drawn up for IM injection?",f:"IM epinephrine: 0.01 mg/kg, maximum 0.5 mg in adults; 1 mg/mL means 1 mg per mL",ch:[["0.5 mL",""],["0.6 mL","This does not apply the 0.5 mg maximum."],["6 mL","This is ten times the dose."],["0.05 mL","This is ten times too little."]]},
'asthma/pef':{f:"PEF % predicted = measured ÷ predicted × 100",ch:[["30%",""],["70%","This is the shortfall from predicted, not the percentage achieved."],["3.3%","This misplaces the decimal point."],["35%","Recheck the division: 150 ÷ 500."]]},
'sepsis/fl':{q:"She weighs 50 kg. How much crystalloid is the initial bolus for sepsis-induced hypotension?",f:"Initial bolus: 30 mL/kg of crystalloid within the first 3 hours",ch:[["1,500 mL",""],["500 mL","This uses 10 mL/kg."],["3,000 mL","This uses 60 mL/kg."],["150 mL","Multiply 30 mL/kg by her weight."]]},
'op/cum':{ch:[["30 mg",""],["16 mg","This is only the last dose."],["32 mg","This adds an extra doubling."],["14 mg","This leaves out the last dose."]]},
'rabies/rig':{q:"Bea weighs 25 kg. What is her dose of human rabies immunoglobulin (HRIG)?",f:"HRIG 20 IU/kg (equine RIG 40 IU/kg)",ch:[["500 IU",""],["1,000 IU","This uses 40 IU/kg, the dose of equine RIG."],["250 IU","This uses 10 IU/kg."],["45 IU","Multiply, do not add, the dose and the weight."]]},
'stab/pp':{ch:[["16 mm Hg",""],["184 mm Hg","Subtract the two values; do not add them."],["8 mm Hg","This halves the difference."],["84 mm Hg","This is the inspiratory systolic pressure, not the fall."]]},
'burn/park':{q:"She weighs 70 kg with 27% TBSA burns. Using the Parkland formula, what is the total fluid for the first 24 hours?",f:"Parkland: 4 mL × weight (kg) × %TBSA over 24 hours; half in the first 8 hours from the time of the burn",ch:[["7,560 mL",""],["3,780 mL","This is only the first 8 hours."],["1,890 mL","This uses 1 mL/kg/%TBSA."],["15,120 mL","This uses 8 mL/kg/%TBSA."]]}
