 s+='<div class="cx-play"><aside class="cx-side">'+monHTML()+'<div class="cx-pt s0" id="cxPt">'+avatar(CASES[CUR].av)+'<div><b>'+h(CASES[CUR].pt)+'</b><span>Improving</span></div></div>'+
  '<div class="cx-score"><div><small>Case score</small><b>'+Math.max(0,c.pts)+'<i> / '+maxPts(CUR)+'</i></b></div><div><small>Harm events</small><b class="'+(c.harm?'bad':'')+'">'+c.harm+'</b></div></div>'+wheel(covered(),'Subjects covered so far')+'</aside>';
 s+='<main class="cx-scene"><div class="cx-sh"><span class="pl">📍 '+h(sc.place)+'</span><span class="tm">🕒 '+h(sc.time)+'</span>'+(sc.s.length?'<span class="sj">'+sc.s.map(function(k){return '<em style="--k:'+SUBJ[k][2]+'">'+SUBJ[k][1]+' '+SUBJ[k][0]+'</em>'}).join('')+'</span>':'')+'</div><h3 class="cx-h">Scene '+(c.i+1)+' · '+h(sc.title)+'</h3>'+ixHTML();
 s+=sc.b.map(function(b,bi){return block(b,bi)}).join('');
 s+='<div class="cx-next">'+(c.i>0?'<button type="button" class="btn ghost sm" data-cx="prev">← Previous scene</button>':'')+'<span class="need" id="cxNeed"></span><span class="sp"></span>'+(c.i<S().length-1?'<button type="button" class="btn" data-cx="next" id="cxNext">Next scene →</button>':'<button type="button" class="btn" data-cx="finish" id="cxNext">Finish the case</button>')+'</div></main></div>';
 root.innerHTML=s;
 var v=c.v&&c.vi===c.i?c.v:sc.v; if(!(c.v&&c.vi===c.i)){c.v=JSON.parse(JSON.stringify(sc.v)); c.vi=c.i; save()} V=null; paintMon(v,true); var X0=curIx(); if(X0&&X0.self&&!(c.ixOn&&c.ixOn[c.i])){c.ixOn=c.ixOn||{}; c.ixOn[c.i]=1; applyEff(X0.on)}
