function perm(key,n){var a=[],h=2166136261; for(var i=0;i<n;i++)a.push(i); for(i=0;i<key.length;i++){h^=key.charCodeAt(i); h=Math.imul(h,16777619)>>>0}
 var r=function(){h=(h+0x6D2B79F5)>>>0; var t=h; t=Math.imul(t^(t>>>15),t|1); t^=t+Math.imul(t^(t>>>7),t|61); return ((t^(t>>>14))>>>0)/4294967296};
 for(i=n-1;i>0;i--){var j=Math.floor(r()*(i+1)), t=a[i]; a[i]=a[j]; a[j]=t} return a}
function done(id){return cs().d[id]}
