function sat(p){var x=Math.pow(p,3)+150*p; return 100/(1+23400/x)}
function o2curve(d){var W=300,H=170, X=function(p){return 30+p/200*(W-40)}, Y=function(s){return H-20-(s/100)*(H-35)}, path='';
 for(var p=1;p<=200;p+=3)path+=(p===1?'M':'L')+X(p).toFixed(1)+' '+Y(sat(p)).toFixed(1);
 var px=X(d[1]), py=Y(d[2]);
 return '<svg viewBox="0 0 '+W+' '+H+'" class="cx-curve" role="img" aria-label="Oxyhemoglobin dissociation curve"><rect x="30" y="'+Y(98)+'" width="'+(W-40)+'" height="'+(Y(94)-Y(98))+'" class="tgt"/><line x1="30" y1="'+(H-20)+'" x2="'+(W-10)+'" y2="'+(H-20)+'" class="ax"/><line x1="30" y1="15" x2="30" y2="'+(H-20)+'" class="ax"/><path d="'+path+'" class="crv"/>'+
  [0,50,100,150,200].map(function(v){return '<text x="'+X(v)+'" y="'+(H-6)+'" text-anchor="middle">'+v+'</text>'}).join('')+[50,75,90,100].map(function(v){return '<text x="24" y="'+(Y(v)+3)+'" text-anchor="end">'+v+'</text>'}).join('')+
  '<line x1="'+px+'" y1="'+py+'" x2="'+px+'" y2="'+(H-20)+'" class="gd"/><line x1="30" y1="'+py+'" x2="'+px+'" y2="'+py+'" class="gd"/><circle cx="'+px+'" cy="'+py+'" r="6" class="pt"/><text x="'+Math.min(px+8,190)+'" y="'+(py+16)+'" class="lbl">PaO₂ '+d[1]+' · SpO₂ '+d[2]+'%</text><text x="'+(W-12)+'" y="'+(H-24)+'" text-anchor="end">PaO₂ (mm Hg)</text><text x="34" y="12">SaO₂ (%)</text></svg>'}
var RISK=[['RR ≥ 30 breaths/min',1],['Pulse rate ≥ 125/min',0],['Temperature ≥ 40 °C or ≤ 36 °C',0],['SBP < 90 or DBP ≤ 60 mm Hg',1],['Altered mental state of acute onset',0],['Suspected aspiration',0],['Decompensated comorbidity (e.g., DKA, heart failure)',0],['Multilobar infiltrates, pleural effusion or abscess on x-ray',0]];
function curb(){var r=[['Confusion','No',0],['Urea > 7 mmol/L (BUN > 19 mg/dL)','8.6 mmol/L',1],['Respiratory rate ≥ 30','32',1],['BP: SBP < 90 or DBP ≤ 60','100/60',1],['Age ≥ 65','68',1]]; return '<table class="cx-lab curb"><caption>CURB-65 = 4: high 30-day mortality, so watch closely and escalate early if he worsens</caption>'+r.map(function(x){return '<tr><td>'+x[0]+'</td><td>'+x[1]+'</td><td class="'+(x[2]?'hi':'')+'">'+x[2]+'</td></tr>'}).join('')+'</table>'}
var TESTS=[['Chest x-ray (PA, lateral)',450,1,1],['CBC with differential',350,1,1],['Blood culture, 2 sites',2400,48,1],['Sputum Gram stain and culture',900,48,1],['BUN, creatinine, electrolytes, RBS',900,2,1],['Chest CT scan with contrast',9500,6,-1],['Bronchoscopy with lavage',18000,24,-1],['Mycoplasma serology',1800,72,-1],['Procalcitonin',2500,4,0],['ECG',300,0.5,0]];
