 for(var cm=65;cm<=105;cm+=10)s+='<line x1="'+X(cm)+'" x2="'+X(cm)+'" y1="'+T+'" y2="'+(H-B)+'" stroke="currentColor" opacity=".08"/><text x="'+X(cm)+'" y="'+(H-B+15)+'" font-size="10" text-anchor="middle" fill="currentColor">'+cm+'</text>';
