/* ---------- lung sounds (synthesized, no files) ---------- */
var AC=null;
function lungSound(ab){try{AC=AC||new (window.AudioContext||window.webkitAudioContext)(); var len=AC.sampleRate*2.6, buf=AC.createBuffer(1,len,AC.sampleRate), d=buf.getChannelData(0);
 for(var i=0;i<len;i++){var t=i/AC.sampleRate, ph=t%2.6, env=ph<1.1?Math.sin(Math.PI*ph/1.1):(ph<2.3?.6*Math.sin(Math.PI*(ph-1.1)/1.2):0); d[i]=(Math.random()*2-1)*env*(ab?.55:.25);
  if(ab&&ph>0.6&&ph<1.05&&Math.random()<.0009){for(var k=0;k<60&&i+k<len;k++)d[i+k]+=Math.sin(k*1.3)*Math.exp(-k/12)*.9}}
 var src=AC.createBufferSource(); src.buffer=buf; var f=AC.createBiquadFilter(); f.type=ab?'bandpass':'lowpass'; f.frequency.value=ab?700:400; f.Q.value=ab?.9:.7; var g=AC.createGain(); g.gain.value=.8; src.connect(f); f.connect(g); g.connect(AC.destination); src.start()}catch(e){}}

