/* ---------- cover music: Chill Cozy Café, looping until the student stops or mutes it ---------- */
(function(){
var src=null; /* the music is unpacked only when it is first needed */
var bad=false, blocked=false, A=null, url=null, st={v:0.2,m:false}, stopped=false, wanted=false, held=false, fadeT=0, duck=false;
try{var o=JSON.parse(store.get('ple27cafe')||'null'); if(o){st.v=typeof o.v==='number'?o.v:0.2; st.m=!!o.m}}catch(e){}
function keep(){store.set('ple27cafe',JSON.stringify(st))}
var HOLD={jackpot:1,wheel:1,snakes:1,podcasts:1,drm:1};
/* the bar */
addEventListener('load',function(){setTimeout(function(){audio()},2500)});
var bar=document.createElement('div'); bar.className='cf-bar'; bar.setAttribute('role','region'); bar.setAttribute('aria-label','Music');
bar.innerHTML='<button type="button" class="cf-ic" data-cf="open" aria-label="Music controls" aria-expanded="true"><span class="cf-eq" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span class="cf-note">🎵</span></button>'+
 '<div class="cf-body"><div class="cf-t"><b>Chill Cozy Café</b><span id="cfState">Plays on the cover</span></div>'+
 '<button type="button" class="cf-b" data-cf="play" aria-label="Play">▶</button><button type="button" class="cf-b" data-cf="stop" aria-label="Stop">■</button>'+
 '<button type="button" class="cf-b" data-cf="mute" aria-label="Mute">🔊</button>'+
 '<input type="range" class="cf-vol" min="0" max="100" step="1" aria-label="Music volume"><span class="cf-pct" aria-hidden="true"></span>'+
 '<button type="button" class="cf-x" data-cf="fold" aria-label="Hide the music controls">×</button></div>';
document.body.appendChild(bar);
var vol=$('.cf-vol',bar), pctEl=$('.cf-pct',bar);
if(window.innerWidth<=760)bar.classList.add('fold');
function audio(){ if(A)return A; A=new Audio(); A.loop=true; A.preload='auto'; A.setAttribute('playsinline','');
  function fill(){src=document.getElementById('bgCafe'); if(!src){bad=true; paint(); return}
  var f=src.getAttribute('data-file');
  if(f){fetch(f).then(function(r){return r.blob()}).then(function(bl){url=URL.createObjectURL(bl); A.src=url; if(wanted&&!held)play(false)}).catch(function(){A.src=f})} else{try{var bin=atob(src.textContent.trim()), u=new Uint8Array(bin.length); for(var i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i); url=URL.createObjectURL(new Blob([u],{type:src.getAttribute('data-mime')||'audio/mpeg'})); A.src=url}catch(e){}}
  if(A.src&&wanted&&!held)try{play(false)}catch(_){}}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',fill); else fill();
  A.volume=st.v; A.muted=st.m; A.addEventListener('error',function(){bad=true; paint()});
  A.addEventListener('play',paint); A.addEventListener('pause',paint);
  try{ if('mediaSession' in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:'Chill Cozy Café',artist:'My Med APP by PLE REAP'}); navigator.mediaSession.setActionHandler('play',function(){play(true)}); navigator.mediaSession.setActionHandler('pause',function(){pause()}); navigator.mediaSession.setActionHandler('stop',function(){stop()})}}catch(e){}
  return A}
function fadeTo(v,ms,done){clearInterval(fadeT); var a=audio(), s=a.volume, t0=Date.now(); fadeT=setInterval(function(){var k=Math.min(1,(Date.now()-t0)/ms); a.volume=Math.max(0,Math.min(1,s+(v-s)*k)); if(k>=1){clearInterval(fadeT); if(done)done()}},40)}
function play(user){var a=audio(); if(user){stopped=false; duck=false} wanted=true; if((held||duck)&&!user)return paint();
  var start=a.paused; if(start)a.volume=0;
  var p=a.play(); if(p&&p.catch)p.then(function(){blocked=false; if(duck&&!user){a.pause(); a.volume=st.v; return paint()} if(start)fadeTo(st.v,900); paint()},function(){blocked=true; a.volume=st.v; waitGesture(); paint()}); paint()}
function pause(){ if(!A)return; wanted=false; fadeTo(0,350,function(){A.pause(); A.volume=st.v}); paint()}
function stop(){ if(!A)return; stopped=true; wanted=false; fadeTo(0,350,function(){A.pause(); A.currentTime=0; A.volume=st.v; paint()}); paint()}
var gw=false;
function waitGesture(){ if(gw)return; gw=true; function go(){gw=false; ['pointerdown','keydown','touchend'].forEach(function(e){document.removeEventListener(e,go,true)}); if(wanted&&!stopped&&!held&&!duck)play(false)}
  ['pointerdown','keydown','touchend'].forEach(function(e){document.addEventListener(e,go,true)})}
function paint(){var on=A&&!A.paused; bar.classList.toggle('on',!!on); bar.classList.toggle('muted',st.m); bar.classList.toggle('wait',blocked&&wanted&&!(A&&!A.paused));
  var pb=$('[data-cf="play"]',bar); pb.textContent=on?'❚❚':'▶'; pb.setAttribute('aria-label',on?'Pause':'Play');
  var mb=$('[data-cf="mute"]',bar); mb.textContent=st.m||st.v===0?'🔇':st.v<.4?'🔈':'🔊'; mb.setAttribute('aria-label',st.m?'Unmute':'Mute'); mb.setAttribute('aria-pressed',st.m?'true':'false');
  vol.value=Math.round(st.v*100); vol.style.setProperty('--p',Math.round(st.v*100)+'%'); pctEl.textContent=Math.round(st.v*100)+'%';
  $('#cfState').textContent=bad?'This browser could not play the music':blocked&&wanted&&!on?'Tap anywhere to start the music':held&&wanted?'Paused while this plate plays its own audio':duck&&wanted?'Paused while the avatar walks by':on?(st.m?'Muted · still looping':'Now playing · on loop'):stopped?'Stopped · press ▶ to play':'Paused'}
bar.addEventListener('click',function(e){var b=e.target.closest('[data-cf]'); if(!b)return; var c=b.dataset.cf;
  if(c==='play'){ if(A&&!A.paused)pause(); else{held=false; play(true)}}
  else if(c==='stop')stop();
  else if(c==='mute'){st.m=!st.m; if(!st.m&&st.v===0)st.v=.2; keep(); var a=audio(); a.muted=st.m; a.volume=st.v; if(!st.m&&a.paused&&!stopped)play(true); paint()}
  else if(c==='fold'){bar.classList.add('fold'); $('[data-cf="open"]',bar).setAttribute('aria-expanded','false')}
  else if(c==='open'){var f=bar.classList.toggle('fold'); b.setAttribute('aria-expanded',f?'false':'true')}});
vol.addEventListener('input',function(){st.v=vol.value/100; clearInterval(fadeT); var a=audio(); a.volume=st.v; if(st.v>0&&st.m){st.m=false; a.muted=false} keep(); paint()});
/* starts on the cover; keeps looping across plates; steps aside for plates with their own audio */
document.addEventListener('plate',function(e){var id=e.detail;
  if(HOLD[id]){ if(A&&!A.paused){held=true; fadeTo(0,400,function(){A.pause(); A.volume=st.v; paint()})} else held=!!wanted; paint(); return}
  if(held){held=false; if(wanted&&!stopped)play(false)}
  if(id==='cover'&&!stopped&&!(A&&!A.paused))play(false)});
/* Let's Build: the walking avatar brings his own tune, so the café steps aside until he is gone */
var duckT=0;
document.addEventListener('drmwalk',function(e){clearTimeout(duckT);
  if(e.detail==='start'){duck=true; if(A&&!A.paused)fadeTo(0,300,function(){if(duck){A.pause(); A.volume=st.v} paint()}); paint()}
  else if(duck)duckT=setTimeout(function(){duck=false; if(wanted&&!stopped&&!held)play(false); else paint()},180)});
wanted=true; play(false);
paint();
})();



/* ---------- 🎄 Christmas theme: snow, lights, parols, festive sheets ---------- */
(function(){
var BUL=['#3D8BFF','#BFE3FF','#FFFFFF','#6FA8FF','#C3CEDD'];
function lights(n){var s='<div class="xm-lights" aria-hidden="true">'; for(var i=0;i<n;i++)s+='<i style="--b:'+BUL[i%BUL.length]+';--d:'+(-(i*0.37)%2.4).toFixed(2)+'s"></i>'; return s+'</div>'}
$$('.ph').forEach(function(h){h.insertAdjacentHTML('afterbegin','<div class="xm-cap" aria-hidden="true"></div>')});
var br=$('.brand'); if(br)br.insertAdjacentHTML('beforeend','<span class="xm-parol xm-brandp" aria-hidden="true"></span>');
var hero=$('.hero'); if(hero){hero.insertAdjacentHTML('afterbegin','<span class="xm-parol l" aria-hidden="true"></span><span class="xm-parol r" aria-hidden="true"></span>'); var t=hero.querySelector('.sealwrap'); if(t)t.insertAdjacentHTML('beforebegin','<span class="xm-ribbon">❄️ Maligayang Pasko mula sa My Med APP! 💙</span>')}
var en=$('#entry'); if(en){en.insertAdjacentHTML('afterbegin','<span class="xm-parol l" aria-hidden="true"></span><span class="xm-parol r" aria-hidden="true"></span>'); var ei=en.querySelector('.en-in'); if(ei)ei.insertAdjacentHTML('afterbegin','<span class="xm-ribbon">❄️ Maligayang Pasko at Manigong Bagong Taon! 💙</span>')}

/* snow toggle in the rail and the phone top bar */
var tools=$('.rail .tools'), tb=$('.topbar .tb-r');
if(tools)tools.insertAdjacentHTML('beforeend','<button type="button" id="snowBtn" aria-pressed="true">Snow</button>');
if(tb)tb.insertAdjacentHTML('afterbegin','<button type="button" id="snowBtn2" aria-pressed="true" aria-label="Snowfall">❄</button>');
var off=store.get('ple27snow')==='0'||(reduce&&store.get('ple27snow')!=='1');
function paintSnow(){document.documentElement.classList.toggle('no-snow',off); ['#snowBtn','#snowBtn2'].forEach(function(q){var b=$(q); if(!b)return; b.setAttribute('aria-pressed',off?'false':'true'); b.classList.toggle('on',!off)}); var b1=$('#snowBtn'); if(b1)b1.textContent=off?'Snow':'Snow ✓'; if(!off)startSnow()}
['#snowBtn','#snowBtn2'].forEach(function(q){var b=$(q); if(b)b.addEventListener('click',function(){off=!off; store.set('ple27snow',off?'0':'1'); paintSnow()})});

/* snowfall */
var cv=document.createElement('canvas'); cv.id='xmSnow'; cv.setAttribute('aria-hidden','true'); document.body.appendChild(cv);
var cx=cv.getContext('2d'), F=[], W=0, H=0, run=false, dpr=Math.min(2,window.devicePixelRatio||1);
function size(){W=innerWidth; H=innerHeight; cv.width=W*dpr; cv.height=H*dpr; cx.setTransform(dpr,0,0,dpr,0,0); var n=Math.round(Math.min(14,Math.max(5,W*H/100000))); while(F.length<n)F.push(flake(true)); F.length=n}
function flake(any){var k=Math.random()<.15; return {x:Math.random()*W,y:any?Math.random()*H:-10,r:.7+Math.random()*1.7,v:.25+Math.random()*.6,w:Math.random()*6.28,s:.3+Math.random()*.6,k:k,R:k?3+Math.random()*3:0,a:Math.random()*6.28,va:(Math.random()-.5)*.02}}
function crystal(f){var R=f.R; cx.save(); cx.translate(f.x,f.y); cx.rotate(f.a); cx.strokeStyle='rgba(235,245,255,'+(0.55+R/30)+')'; cx.lineWidth=1; cx.lineCap='round'; cx.shadowColor='rgba(120,175,255,.8)'; cx.shadowBlur=3; cx.beginPath();
  for(var j=0;j<6;j++){cx.rotate(1.0472); cx.moveTo(0,0); cx.lineTo(0,-R); cx.moveTo(0,-R*.55); cx.lineTo(R*.28,-R*.8); cx.moveTo(0,-R*.55); cx.lineTo(-R*.28,-R*.8)} cx.stroke(); cx.restore()}
function tick(){ if(off||document.hidden){run=false; return} cx.clearRect(0,0,W,H);
  for(var i=0;i<F.length;i++){var f=F[i]; f.y+=f.v; f.w+=.012; f.x+=Math.sin(f.w)*f.s*.6; if(f.y>H+6||f.x<-10||f.x>W+10){F[i]=flake(false); continue}
    if(f.k){f.a+=f.va; crystal(f); continue}
    cx.beginPath(); cx.arc(f.x,f.y,f.r,0,6.283); cx.fillStyle='rgba(255,255,255,'+(0.4+f.r/10)+')'; cx.shadowColor='rgba(70,120,200,.55)'; cx.shadowBlur=2; cx.fill()}
  requestAnimationFrame(tick)}
function startSnow(){ if(run||off)return; run=true; requestAnimationFrame(tick)}
addEventListener('resize',size); document.addEventListener('visibilitychange',function(){ if(!document.hidden)startSnow()});
size(); paintSnow();

/* a festive strip on the review sheets */
var CSS='body::before{content:"";position:absolute;left:0;right:0;top:0;height:12px;z-index:9999;pointer-events:none;background:radial-gradient(circle at 10px 0,#fff 9px,transparent 10px) 0 0/20px 12px repeat-x,linear-gradient(#1E5BB8,#1E5BB8) 0 0/100% 4px no-repeat}';
function deck(f){try{var d=f.contentDocument; if(!d||!d.head||d.getElementById('xmCss'))return; var st=d.createElement('style'); st.id='xmCss'; st.textContent=CSS; d.head.appendChild(st)}catch(e){}}
['#bpFrame','#mcFrame'].forEach(function(id){var box=$(id); if(!box)return; new MutationObserver(function(){$$('iframe',box).forEach(function(f){ if(!f._xm){f._xm=1; f.addEventListener('load',function(){deck(f)})} deck(f)})}).observe(box,{childList:true})});

/* 💙 frost on the edges and twinkling glints on the entry screen and the cover */
function glints(n){var s='<span class="xm-glints" aria-hidden="true">'; for(var i=0;i<n;i++)s+='<i style="left:'+(4+Math.random()*92).toFixed(1)+'%;top:'+(3+Math.random()*55).toFixed(1)+'%;--z:'+(10+Math.random()*12).toFixed(0)+'px;--t:'+(3.5+Math.random()*4).toFixed(1)+'s;--d:'+(-Math.random()*7).toFixed(1)+'s"></i>'; return s+'</span>'}
[hero,en].forEach(function(el){ if(el)el.insertAdjacentHTML('afterbegin','<span class="xm-frost" aria-hidden="true"></span>'+glints(window.innerWidth<700?7:12))});

/* 💙 celebrations: snowflakes and blue-silver confetti join the party */
function snowBurst(n){ if(reduce)return; var c=document.createElement('canvas'); c.setAttribute('aria-hidden','true'); c.style.cssText='position:fixed;inset:0;width:100vw;height:100vh;z-index:2147482600;pointer-events:none'; document.body.appendChild(c);
  var x=c.getContext('2d'), d=Math.min(2,devicePixelRatio||1), w=innerWidth, h=innerHeight; c.width=w*d; c.height=h*d; x.setTransform(d,0,0,d,0,0);
  var C=['#1E5BB8','#3D8BFF','#BFE3FF','#FFFFFF','#C3CEDD','#7FB2FF'], P=[];
  for(var i=0;i<n;i++)P.push({x:Math.random()*w,y:-20-Math.random()*h*.6,vx:(Math.random()-.5)*1.6,vy:1.6+Math.random()*2.4,a:Math.random()*6.28,va:(Math.random()-.5)*.12,s:6+Math.random()*9,f:Math.random()<.4,c:C[Math.floor(Math.random()*C.length)]});
  var t0=performance.now();
  (function f(now){ var age=now-t0; x.clearRect(0,0,w,h); var live=0;
    for(var i=0;i<P.length;i++){var p=P[i]; p.x+=p.vx+Math.sin((now/600)+i)*.4; p.y+=p.vy; p.a+=p.va; if(p.y>h+20)continue; live++;
      x.save(); x.translate(p.x,p.y); x.rotate(p.a); x.globalAlpha=age>4200?Math.max(0,1-(age-4200)/800):1;
      if(p.f){x.strokeStyle='#F2F8FF'; x.lineWidth=1.4; x.shadowColor='rgba(110,170,255,.9)'; x.shadowBlur=4; x.beginPath(); for(var j=0;j<6;j++){x.rotate(1.0472); x.moveTo(0,0); x.lineTo(0,-p.s); x.moveTo(0,-p.s*.55); x.lineTo(p.s*.3,-p.s*.82); x.moveTo(0,-p.s*.55); x.lineTo(-p.s*.3,-p.s*.82)} x.stroke()}
      else{x.fillStyle=p.c; x.fillRect(-p.s/2,-p.s/4,p.s,p.s/2)}
      x.restore()}
    if(live&&age<5000)requestAnimationFrame(f); else c.remove()})(t0)}
window.xmSnowBurst=snowBurst;
new MutationObserver(function(ms){ms.forEach(function(m){m.addedNodes.forEach(function(nd){ if(nd.nodeType!==1||!nd.classList)return;
  if(nd.classList.contains('drm-wel')){var bub=nd.querySelector('.dw-bub'); if(bub&&!bub.querySelector('.xm-bubsnow')){var h='<span class="xm-bubsnow" aria-hidden="true">';
    for(var q=0;q<26;q++){var f=q%3!==2, z=f?(13+Math.random()*13):(4+Math.random()*4); h+='<i class="'+(f?'':'dot')+'" style="--x:'+(Math.random()*96).toFixed(1)+'%;--y:'+(Math.random()*90).toFixed(0)+'%;--z:'+z.toFixed(1)+'px;--o:'+(f?.55+Math.random()*.3:.45+Math.random()*.3).toFixed(2)+';--c:'+(['#6FAEE8','#8EC1EE','#5E9FDD','#9CCAF2'][q%4])+';--t:'+(5+Math.random()*5).toFixed(1)+'s;--d:'+(-Math.random()*10).toFixed(1)+'s;--w:'+((Math.random()-.5)*30).toFixed(0)+'px">'+(f?'❄':'')+'</i>'}
    bub.insertAdjacentHTML('afterbegin',h+'</span>')}}
  if(nd.classList.contains('jp-ban')&&!nd.classList.contains('lost'))snowBurst(110);
  else if(nd.classList.contains('wv-flash')&&nd.classList.contains('fs'))snowBurst(70)})})}).observe(document.body,{childList:true});
})();


